import json,pathlib
p=pathlib.Path('public/data')
def save(n,x):(p/n).write_text(json.dumps(x,indent=2))
q=json.loads((p/'queens-source.json').read_text())['response']['result']['addressMatches'][0]['coordinates']
e=json.loads((p/'east-windsor-source.json').read_text())['response']['result']['addressMatches'][0]['coordinates']
coords={'Hyderabad':{'lat':17.38405,'lng':78.45636,'source':'https://www.geonames.org/1269843/hyderabad.html','accuracy':'city reference point, not factory'},'Pennington':{'lat':40.324924,'lng':-74.788780,'source':'https://www.latlong.net/place/pennington-nj-usa-28897.html','accuracy':'city reference point, not a facility'},'Queens':{'lat':q['y'],'lng':q['x'],'source':'/data/queens-source.json'},'East Windsor':{'lat':e['y'],'lng':e['x'],'source':'/data/east-windsor-source.json'}}
save('coordinates.json',coords)
def stop(role,company,city,country,ev,note,what,risk,src):
 c=coords.get(city,{})
 return {'role':role,'company':company,'city':city,'country':country,'lat':c.get('lat'),'lng':c.get('lng'),'evidence':ev,'note':note,'what':what,'risk':risk,'sources':src+(['coordinates'] if c else []),'_review':'pending'}
unknownapi=stop('Active ingredient',None,None,None,'illustrative','API supplier and synthesis site are not identified by these bottle labels. No pin is invented.','Chemical synthesis produces the active pharmaceutical ingredient. This is a typical manufacturing stage, not a verified supplier for this product.','Raw-material or quality problems can interrupt supply.',['registration','fda'])
unknownwholesale=stop('Wholesale',None,None,'United States','illustrative','No wholesaler or distribution center is confirmed for this bottle.','A wholesaler may consolidate, store and deliver finished medicines. The route here is not documented.','Inventory or transport disruption can delay delivery.',['registration','fda'])
pharmacy=stop('Pharmacy','CVS Pharmacy','Queens','United States','illustrative','Real pharmacy, illustrative destination. Neither receipt nor stock of this NDC is verified.','The pharmacy is on Hillside Avenue in Queens. This story ends at a real address, without claiming a tracked delivery.','Local stock may differ from a manufacturer’s national supply.',['pharmacy','fda'])
a=[unknownapi,stop('Tablets made','Aurobindo Pharma Limited','Hyderabad','India','verified','Verified manufacturer statement and city on label; exact plant and batch are unknown.','The label names the manufacturer in Hyderabad. Formulation and tablet production turn active ingredient into a finished medicine.','Manufacturing or quality delays can reduce availability.',['label','fda']),stop('Label & distribution','Aurobindo Pharma USA, Inc.','East Windsor','United States','verified','Verified distributor address. It is not evidence that this bottle passed through the address.','The US label identifies Aurobindo Pharma USA as distributor. The NDC identifies the product and package, not its shipping history.','Labeling or distribution problems can interrupt supply.',['label','registration','fda']),unknownwholesale,pharmacy]
z=[unknownapi,stop('Tablets made','Zydus Lifesciences Limited',None,'India','verified','Label says made in India; the exact manufacturing facility is not located.','The label and establishment table identify Indian manufacture. No city is inferred from a corporate headquarters.','Manufacturing or quality delays can reduce availability.',['zydus','fda']),stop('Label & distribution','Zydus Pharmaceuticals (USA) Inc.','Pennington','United States','verified','Verified label distributor city. Pin is a city reference, not a warehouse.','The US label identifies the distributor in Pennington. This second product shares an active ingredient but not an evidenced supply chain.','Distributor inventory and delivery patterns can differ.',['zydus','fda']),unknownwholesale,pharmacy]
save('journey.json',{'_review':'pending','drug':'Carvedilol','strength':'25 mg','package':'100 tablets','sourceNote':'Product-label reconstruction; not a tracked physical bottle. Every arc is illustrative. Strength identifies the package, not an instruction to take it.','bottles':[{'id':'aurobindo','name':'Aurobindo','ndc':'65862-145-01','sources':['label'],'stops':a},{'id':'zydus','name':'Zydus','ndc':'68382-095-01','sources':['zydus'],'stops':z}]})
save('api_sites.json',{'_review':'pending','status':'unverified','countries':[],'note':'No verified drug-specific API site counts are available in this dataset. Unknown does not mean zero. FDA registration alone does not establish that a site makes carvedilol for either NDC.','sources':['registration']})
save('shortages.json',{'_review':'pending','status':'unverified','records':[],'note':'A complete FDA shortage history has not been verified. This is not a claim that carvedilol has never been in shortage.','sources':['fda']})
